use vstd::prelude::*;

verus! {

spec fn putmask_spec(a: Seq<f32>, mask: Seq<bool>, values: Seq<f32>) -> Seq<f32>
    recommends
        a.len() == mask.len(),
        values.len() > 0,
{
    let m = values.len();
    Seq::new(a.len(), |i: int| if mask[i] { values[i % m] } else { a[i] })
}

fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> (result: Vec<f32>)
    requires
        a@.len() == mask@.len(),
        values@.len() > 0,
    ensures
        result@ == putmask_spec(a@, mask@, values@),
        result@.len() == a@.len(),
{
    assert_eq!(a.len(), mask.len(), "mask must have same length as a");
    assert!(!values.is_empty(), "values must be non-empty");

    let m = values.len();
    let mut result = Vec::with_capacity(a.len());

    for (i, (ai, mi)) in a.into_iter().zip(mask.into_iter()).enumerate()
        invariant
            m == values@.len(),
            m > 0,
            result@.len() == i,
            i <= putmask_spec(a@, mask@, values@).len(),
            result@ == putmask_spec(a@, mask@, values@).subrange(0, i as int),
        decreases
            putmask_spec(a@, mask@, values@).len() - i,
    {
        if mi {
            // i < a.len() == mask.len() and m > 0, so i % m is in-bounds for values
            result.push(values[i % m]);
        } else {
            result.push(ai);
        }
    }

    result
}

} // verus!

